/* ============================================================
   GlobalStone — Design System
   Colors in OKLCH with hex fallbacks
   ============================================================ */

:root {
  /* Brand colors */
  --color-primary: oklch(23% 0.06 195);
  --color-primary-hex: #012A2D;
  --color-secondary: oklch(27% 0.09 170);
  --color-secondary-hex: #003F2D;
  --color-accent: oklch(74% 0.13 90);
  --color-accent-hex: #c9a84c;

  /* Neutrals */
  --color-white: oklch(100% 0 0);
  --color-off-white: oklch(97% 0.005 220);
  --color-light-gray: oklch(91% 0.008 220);
  --color-mid-gray: oklch(65% 0.02 220);
  --color-dark-gray: oklch(35% 0.02 220);
  --color-text: oklch(16% 0.02 225);
  --color-text-light: oklch(45% 0.02 220);

  /* Semantic */
  --color-link: oklch(50% 0.15 250);
  --color-link-hover: oklch(40% 0.16 250);
  --color-cta: oklch(74% 0.13 88);
  --color-cta-hover: oklch(80% 0.14 88);

  /* Typography */
  --font-body: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --font-display: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;

  --text-xs: 0.75rem;
  --text-sm: 0.875rem;
  --text-base: 1rem;
  --text-lg: 1.125rem;
  --text-xl: 1.25rem;
  --text-2xl: 1.5rem;
  --text-3xl: 1.875rem;
  --text-4xl: 2.25rem;
  --text-5xl: 3rem;
  --text-6xl: 3.75rem;

  --leading-tight: 1.15;
  --leading-snug: 1.35;
  --leading-normal: 1.6;

  --weight-normal: 400;
  --weight-medium: 500;
  --weight-semibold: 600;
  --weight-bold: 700;

  /* Spacing scale */
  --space-1: 0.25rem;
  --space-2: 0.5rem;
  --space-3: 0.75rem;
  --space-4: 1rem;
  --space-5: 1.25rem;
  --space-6: 1.5rem;
  --space-8: 2rem;
  --space-10: 2.5rem;
  --space-12: 3rem;
  --space-16: 4rem;
  --space-20: 5rem;
  --space-24: 6rem;
  --space-32: 8rem;

  /* Layout */
  --max-width: 1280px;
  --max-width-narrow: 960px;
  --max-width-wide: 1400px;
  --content-padding: var(--space-6);

  /* Borders & Radius */
  --radius-sm: 4px;
  --radius-md: 6px;
  --radius-lg: 12px;
  --radius-xl: 16px;

  /* Shadows */
  --shadow-sm: 0 1px 2px rgba(0,0,0,0.06);
  --shadow-md: 0 4px 12px rgba(0,0,0,0.08);
  --shadow-lg: 0 8px 30px rgba(0,0,0,0.12);
  --shadow-xl: 0 20px 60px rgba(0,0,0,0.15);

  /* Transitions */
  --transition-fast: 150ms ease;
  --transition-base: 250ms ease;
  --transition-slow: 400ms ease;
}

/* ============================================================
   Reset & Base
   ============================================================ */

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  font-size: 16px;
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-body);
  font-size: var(--text-base);
  line-height: var(--leading-normal);
  color: var(--color-text);
  background-color: var(--color-white);
  min-height: 100vh;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

a {
  color: inherit;
  text-decoration: none;
  transition: color var(--transition-fast);
}

ul, ol {
  list-style: none;
}

button {
  font: inherit;
  cursor: pointer;
  border: none;
  background: none;
  color: inherit;
}

h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-display);
  line-height: var(--leading-tight);
  font-weight: var(--weight-bold);
  color: var(--color-primary);
}

h1 { font-size: var(--text-5xl); }
h2 { font-size: var(--text-4xl); }
h3 { font-size: var(--text-2xl); }
h4 { font-size: var(--text-xl); }

/* ============================================================
   Layout Utilities
   ============================================================ */

.container {
  width: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--content-padding);
}

.container--narrow {
  max-width: var(--max-width-narrow);
}

.container--wide {
  max-width: var(--max-width-wide);
}

.section {
  padding: var(--space-24) 0;
}

.section--sm { padding: var(--space-16) 0; }
.section--lg { padding: var(--space-32) 0; }

.section-label {
  display: inline-block;
  font-size: var(--text-sm);
  font-weight: var(--weight-semibold);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--color-secondary);
  margin-bottom: var(--space-3);
}

.section-title {
  font-size: var(--text-4xl);
  font-weight: var(--weight-bold);
  color: var(--color-primary);
  margin-bottom: var(--space-4);
  line-height: var(--leading-tight);
}

.section-subtitle {
  font-size: var(--text-lg);
  color: var(--color-text-light);
  max-width: 640px;
  line-height: var(--leading-normal);
}

.section-header {
  margin-bottom: var(--space-12);
}

.section-header--centered {
  text-align: center;
}

.section-header--centered .section-subtitle {
  margin: 0 auto;
}

/* ============================================================
   Buttons
   ============================================================ */

.btn {
  display: inline-flex;
  align-items: center;
  gap: var(--space-2);
  font-weight: var(--weight-semibold);
  font-size: var(--text-sm);
  padding: var(--space-3) var(--space-6);
  border-radius: var(--radius-sm);
  transition: all var(--transition-fast);
  white-space: nowrap;
  line-height: 1.4;
}

.btn--primary {
  background: var(--color-cta);
  color: var(--color-primary);
}

.btn--primary:hover {
  background: var(--color-cta-hover);
  transform: translateY(-1px);
}

.btn--outline {
  border: 1.5px solid var(--color-primary);
  color: var(--color-primary);
}

.btn--outline:hover {
  background: var(--color-primary);
  color: var(--color-white);
}

.btn--outline-light {
  border: 1.5px solid rgba(255,255,255,0.5);
  color: var(--color-white);
}

.btn--outline-light:hover {
  background: var(--color-white);
  color: var(--color-primary);
}

.btn--white {
  background: var(--color-white);
  color: var(--color-primary);
}

.btn--white:hover {
  background: var(--color-off-white);
}

.btn--link {
  padding: 0;
  color: var(--color-secondary);
  font-weight: var(--weight-semibold);
}

.btn--link::after {
  content: ' →';
  transition: transform var(--transition-fast);
}

.btn--link:hover::after {
  transform: translateX(4px);
}

.btn--lg {
  padding: var(--space-4) var(--space-8);
  font-size: var(--text-base);
}

/* ============================================================
   Header & Navigation
   ============================================================ */

.header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  background: var(--color-white);
  border-bottom: 1px solid var(--color-light-gray);
  transition: box-shadow var(--transition-base);
}

.header--scrolled {
  box-shadow: var(--shadow-md);
}

.header__inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
  max-width: var(--max-width-wide);
  margin: 0 auto;
  padding: 0 var(--content-padding);
}

.header__logo {
  display: flex;
  align-items: center;
  gap: var(--space-3);
  font-size: var(--text-xl);
  font-weight: var(--weight-bold);
  color: var(--color-primary);
  letter-spacing: -0.02em;
  flex-shrink: 0;
}

.header__logo-icon {
  width: 34px;
  height: 34px;
  border-radius: var(--radius-sm);
  background: var(--color-primary);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-white);
  font-weight: var(--weight-bold);
  font-size: var(--text-base);
}

/* Primary Nav */
.nav {
  display: flex;
  align-items: center;
}

.nav__list {
  display: flex;
  align-items: center;
  gap: var(--space-1);
}

.nav__link {
  display: block;
  padding: var(--space-2) var(--space-3);
  font-size: var(--text-sm);
  font-weight: var(--weight-medium);
  color: var(--color-text);
  border-radius: var(--radius-sm);
  transition: all var(--transition-fast);
  white-space: nowrap;
}

.nav__link:hover,
.nav__link.active {
  color: var(--color-secondary);
  background: oklch(97% 0.01 170);
}

.nav__link.has-dropdown::after {
  content: '';
  display: inline-block;
  width: 6px;
  height: 6px;
  border-right: 1.5px solid currentColor;
  border-bottom: 1.5px solid currentColor;
  transform: rotate(45deg);
  margin-left: var(--space-2);
  vertical-align: middle;
  transition: transform var(--transition-fast);
}

.nav__link.has-dropdown.open::after {
  transform: rotate(-135deg);
  margin-top: -2px;
}

/* Mega Menu */
.mega-menu {
  position: absolute;
  top: 100%;
  left: 0;
  right: 0;
  background: var(--color-white);
  border-top: 1px solid var(--color-light-gray);
  box-shadow: var(--shadow-lg);
  opacity: 0;
  visibility: hidden;
  transform: translateY(-8px);
  transition: all var(--transition-base);
  z-index: 999;
}

.mega-menu--visible {
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
}

.mega-menu__inner {
  max-width: var(--max-width-wide);
  margin: 0 auto;
  padding: var(--space-10) var(--content-padding);
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-12);
}

.mega-menu__column-title {
  font-size: var(--text-xs);
  font-weight: var(--weight-semibold);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--color-mid-gray);
  margin-bottom: var(--space-5);
  padding-bottom: var(--space-3);
  border-bottom: 1px solid var(--color-light-gray);
}

.mega-menu__links {
  display: flex;
  flex-direction: column;
  gap: var(--space-1);
}

.mega-menu__link {
  display: block;
  padding: var(--space-3) var(--space-3);
  font-size: var(--text-sm);
  color: var(--color-text);
  border-radius: var(--radius-sm);
  transition: all var(--transition-fast);
}

.mega-menu__link:hover {
  background: var(--color-off-white);
  color: var(--color-secondary);
  padding-left: var(--space-5);
}

/* Mobile menu toggle */
.mobile-toggle {
  display: none;
  width: 40px;
  height: 40px;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius-sm);
  z-index: 1001;
}

.mobile-toggle:hover {
  background: var(--color-off-white);
}

.mobile-toggle__bar {
  width: 22px;
  height: 2px;
  background: var(--color-primary);
  position: relative;
  transition: background var(--transition-base);
}

.mobile-toggle__bar::before,
.mobile-toggle__bar::after {
  content: '';
  position: absolute;
  left: 0;
  width: 100%;
  height: 2px;
  background: var(--color-primary);
  transition: all var(--transition-base);
}

.mobile-toggle__bar::before { top: -7px; }
.mobile-toggle__bar::after { top: 7px; }

.mobile-toggle--active .mobile-toggle__bar {
  background: transparent;
}

.mobile-toggle--active .mobile-toggle__bar::before {
  top: 0;
  transform: rotate(45deg);
}

.mobile-toggle--active .mobile-toggle__bar::after {
  top: 0;
  transform: rotate(-45deg);
}

/* Mobile Nav */
.mobile-nav {
  display: none;
  position: fixed;
  top: 72px;
  left: 0;
  right: 0;
  bottom: 0;
  background: var(--color-white);
  z-index: 998;
  overflow-y: auto;
  padding: var(--space-4) 0;
  opacity: 0;
  visibility: hidden;
  transition: all var(--transition-base);
}

.mobile-nav--open {
  opacity: 1;
  visibility: visible;
}

.mobile-nav__list {
  padding: 0 var(--content-padding);
}

.mobile-nav__item {
  border-bottom: 1px solid var(--color-light-gray);
}

.mobile-nav__link {
  display: block;
  padding: var(--space-4) 0;
  font-weight: var(--weight-medium);
  color: var(--color-text);
  transition: color var(--transition-fast);
}

.mobile-nav__link:hover {
  color: var(--color-secondary);
}

.mobile-nav__accordion-toggle {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  padding: var(--space-4) 0;
  font-weight: var(--weight-medium);
  color: var(--color-text);
  text-align: left;
}

.mobile-nav__accordion-toggle::after {
  content: '+';
  font-size: var(--text-xl);
  font-weight: var(--weight-normal);
  transition: transform var(--transition-base);
}

.mobile-nav__accordion-toggle--open::after {
  content: '−';
}

.mobile-nav__submenu {
  display: none;
  padding: 0 0 var(--space-4) var(--space-4);
}

.mobile-nav__submenu--open {
  display: block;
}

.mobile-nav__sub-link {
  display: block;
  padding: var(--space-2) 0;
  font-size: var(--text-sm);
  color: var(--color-text-light);
}

.mobile-nav__sub-label {
  font-size: var(--text-xs);
  font-weight: var(--weight-semibold);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--color-mid-gray);
  padding: var(--space-4) 0 var(--space-2) var(--space-4);
}

/* ============================================================
   Hero
   ============================================================ */

.hero {
  position: relative;
  min-height: 85vh;
  display: flex;
  align-items: center;
  background: var(--color-primary);
  overflow: hidden;
  margin-top: 72px;
}

.hero__bg {
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, oklch(20% 0.04 210) 0%, oklch(15% 0.03 230) 50%, oklch(25% 0.06 175) 100%);
}

.hero__bg-pattern {
  position: absolute;
  inset: 0;
  opacity: 0.06;
  background-image:
    linear-gradient(30deg, var(--color-white) 12%, transparent 12.5%, transparent 87%, var(--color-white) 87.5%, var(--color-white)),
    linear-gradient(150deg, var(--color-white) 12%, transparent 12.5%, transparent 87%, var(--color-white) 87.5%, var(--color-white)),
    linear-gradient(30deg, var(--color-white) 12%, transparent 12.5%, transparent 87%, var(--color-white) 87.5%, var(--color-white)),
    linear-gradient(150deg, var(--color-white) 12%, transparent 12.5%, transparent 87%, var(--color-white) 87.5%, var(--color-white));
  background-size: 80px 140px;
  background-position: 0 0, 0 0, 40px 70px, 40px 70px;
}

.hero__content {
  position: relative;
  z-index: 2;
  max-width: 720px;
  padding: var(--space-20) 0;
}

.hero__label {
  display: inline-block;
  font-size: var(--text-sm);
  font-weight: var(--weight-semibold);
  color: var(--color-cta);
  text-transform: uppercase;
  letter-spacing: 0.1em;
  margin-bottom: var(--space-6);
}

.hero__title {
  font-size: var(--text-6xl);
  font-weight: var(--weight-bold);
  color: var(--color-white);
  line-height: 1.1;
  margin-bottom: var(--space-6);
}

.hero__subtitle {
  font-size: var(--text-xl);
  color: oklch(80% 0.02 210);
  line-height: var(--leading-normal);
  margin-bottom: var(--space-8);
  max-width: 560px;
}

/* Hero variants */
.hero--page {
  min-height: 50vh;
}

.hero--page .hero__title {
  font-size: var(--text-5xl);
}

/* ============================================================
   Cards
   ============================================================ */

.card {
  background: var(--color-white);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: all var(--transition-base);
}

.card--shadow {
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--color-light-gray);
}

.card--shadow:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

.card__image {
  width: 100%;
  height: 200px;
  object-fit: cover;
}

.card__body {
  padding: var(--space-6);
}

.card__tag {
  display: inline-block;
  font-size: var(--text-xs);
  font-weight: var(--weight-semibold);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--color-secondary);
  margin-bottom: var(--space-3);
}

.card__title {
  font-size: var(--text-xl);
  font-weight: var(--weight-semibold);
  color: var(--color-primary);
  margin-bottom: var(--space-3);
  line-height: var(--leading-snug);
}

.card__text {
  font-size: var(--text-sm);
  color: var(--color-text-light);
  line-height: var(--leading-normal);
  margin-bottom: var(--space-4);
}

.card__meta {
  font-size: var(--text-xs);
  color: var(--color-mid-gray);
}

/* ============================================================
   Grid layouts
   ============================================================ */

.grid-2 { display: grid; grid-template-columns: repeat(2, 1fr); gap: var(--space-8); }
.grid-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: var(--space-8); }
.grid-4 { display: grid; grid-template-columns: repeat(4, 1fr); gap: var(--space-8); }

/* ============================================================
   What We Do — Vertical Tabs
   ============================================================ */

.what-we-do {
  display: grid;
  grid-template-columns: 320px 1fr;
  gap: var(--space-12);
  align-items: start;
}

.tabs-vertical {
  display: flex;
  flex-direction: column;
  gap: var(--space-1);
  border-right: 1px solid var(--color-light-gray);
  padding-right: var(--space-8);
}

.tab-btn {
  display: block;
  width: 100%;
  text-align: left;
  padding: var(--space-4) var(--space-5);
  font-size: var(--text-base);
  font-weight: var(--weight-medium);
  color: var(--color-text-light);
  border-radius: var(--radius-md);
  transition: all var(--transition-fast);
  border-left: 3px solid transparent;
}

.tab-btn:hover {
  background: var(--color-off-white);
  color: var(--color-text);
}

.tab-btn--active {
  background: oklch(97% 0.01 170);
  color: var(--color-secondary);
  font-weight: var(--weight-semibold);
  border-left-color: var(--color-secondary);
}

.tab-panel {
  display: none;
  animation: fadeIn var(--transition-base) ease;
}

.tab-panel--active {
  display: block;
}

.tab-panel__title {
  font-size: var(--text-3xl);
  font-weight: var(--weight-bold);
  color: var(--color-primary);
  margin-bottom: var(--space-4);
}

.tab-panel__text {
  font-size: var(--text-lg);
  color: var(--color-text-light);
  line-height: var(--leading-normal);
  margin-bottom: var(--space-6);
}

.tab-panel__list {
  margin-bottom: var(--space-8);
}

.tab-panel__list li {
  padding: var(--space-2) 0;
  padding-left: var(--space-6);
  position: relative;
  color: var(--color-text-light);
}

.tab-panel__list li::before {
  content: '';
  position: absolute;
  left: 0;
  top: 12px;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--color-secondary);
}

/* ============================================================
   Featured Insights Strip
   ============================================================ */

.featured-insights {
  padding: var(--space-12) 0;
  background: var(--color-off-white);
}

.featured-insights__grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-8);
}

.featured-card {
  display: flex;
  align-items: flex-start;
  gap: var(--space-4);
}

.featured-card__icon {
  flex-shrink: 0;
  width: 44px;
  height: 44px;
  border-radius: var(--radius-md);
  background: var(--color-primary);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-white);
  font-size: var(--text-lg);
}

.featured-card__title {
  font-size: var(--text-sm);
  font-weight: var(--weight-semibold);
  color: var(--color-primary);
  margin-bottom: var(--space-1);
}

.featured-card__text {
  font-size: var(--text-sm);
  color: var(--color-text-light);
  line-height: var(--leading-normal);
}

/* ============================================================
   Announcement Banner
   ============================================================ */

.announcement-banner {
  background: var(--color-secondary);
  padding: var(--space-5) 0;
}

.announcement-banner__inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-6);
}

.announcement-banner__text {
  color: var(--color-white);
  font-size: var(--text-sm);
  font-weight: var(--weight-medium);
}

.announcement-banner__dot {
  display: inline-block;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--color-cta);
  margin-right: var(--space-3);
  animation: pulse 2s infinite;
}

/* ============================================================
   Newsletter
   ============================================================ */

.newsletter {
  background: var(--color-primary);
  padding: var(--space-20) 0;
}

.newsletter__inner {
  max-width: 640px;
  margin: 0 auto;
  text-align: center;
}

.newsletter__title {
  font-size: var(--text-3xl);
  color: var(--color-white);
  margin-bottom: var(--space-4);
}

.newsletter__text {
  color: oklch(80% 0.02 210);
  font-size: var(--text-lg);
  margin-bottom: var(--space-8);
}

.newsletter__form {
  display: flex;
