  to { opacity: 1; transform: translateY(0); }
}

@keyframes pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.5; }
}

@keyframes slideInUp {
  from { opacity: 0; transform: translateY(20px); }
  to { opacity: 1; transform: translateY(0); }
}

.animate-in {
  animation: slideInUp 0.5s ease both;
}

/* ============================================================
   Responsive — Tablet
   ============================================================ */

@media (max-width: 1024px) {
  :root {
    --text-5xl: 2.5rem;
    --text-6xl: 3rem;
  }

  .grid-4,
  .commitment-grid { grid-template-columns: repeat(2, 1fr); }

  .grid-3,
  .services-grid,
  .insights-grid,
  .capabilities-grid,
  .featured-insights__grid { grid-template-columns: repeat(2, 1fr); }

  .what-we-do {
    grid-template-columns: 240px 1fr;
  }

  .footer__grid {
    grid-template-columns: 1fr 1fr;
  }

  .announcement-banner__inner {
    flex-direction: column;
    text-align: center;
  }
}

/* ============================================================
   Responsive — Mobile
   ============================================================ */

@media (max-width: 768px) {
  :root {
    --text-4xl: 1.75rem;
    --text-5xl: 2rem;
    --text-6xl: 2.5rem;
    --content-padding: var(--space-4);
  }

  .section { padding: var(--space-16) 0; }

  /* Header */
  .header__inner { height: 60px; }

  .nav { display: none; }

  .mobile-toggle { display: flex; }
  .mobile-nav { display: block; }

  /* Hero */
  .hero { min-height: 70vh; margin-top: 60px; }
  .hero--page { min-height: 35vh; }
  .hero__title { font-size: var(--text-4xl); }
  .hero__subtitle { font-size: var(--text-base); }

  /* Grids */
  .grid-2,
  .grid-3,
  .grid-4,
  .services-grid,
  .insights-grid,
  .capabilities-grid,
  .commitment-grid,
  .featured-insights__grid { grid-template-columns: 1fr; }

  /* What We Do */
  .what-we-do {
    grid-template-columns: 1fr;
    gap: var(--space-6);
  }

  .tabs-vertical {
    flex-direction: row;
    overflow-x: auto;
    border-right: none;
    border-bottom: 1px solid var(--color-light-gray);
    padding-right: 0;
    padding-bottom: var(--space-4);
    gap: var(--space-2);
  }

  .tab-btn {
    white-space: nowrap;
    border-left: none;
    border-bottom: 3px solid transparent;
    font-size: var(--text-sm);
    padding: var(--space-3) var(--space-4);
  }

  .tab-btn--active {
    border-left-color: transparent;
    border-bottom-color: var(--color-secondary);
  }

  /* Newsletter */
  .newsletter__form {
    flex-direction: column;
  }

  /* Mega menu */
  .mega-menu__inner {
    grid-template-columns: 1fr;
  }

  /* Footer */
  .footer__grid {
    grid-template-columns: 1fr;
    gap: var(--space-8);
  }

  .footer__bottom {
    flex-direction: column;
    text-align: center;
  }

  .footer__legal {
    justify-content: center;
  }

  /* Breadcrumb */
  .breadcrumb { margin-top: 60px; }

  /* Detail pages */
  .partnership-highlight__stats {
    flex-direction: column;
    gap: var(--space-6);
  }

  .property-types-bar {
    flex-direction: column;
    text-align: center;
  }

  .about-statement__text {
    font-size: var(--text-lg);
  }
}

/* ============================================================
   Large screens
   ============================================================ */

@media (min-width: 1400px) {
  .hero__title {
    font-size: 4rem;
  }
}

