  --shadow-lg: 0 8px 30px rgba(0,0,0,0.12);
  --shadow-xl: 0 20px 60px rgba(0,0,0,0.15);

  /* Transitions */
  --transition-fast: 150ms ease;
  --transition-base: 250ms ease;
  --transition-slow: 400ms ease;
}

/* ============================================================
   Reset & Base
   ============================================================ */

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  font-size: 16px;
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-body);
  font-size: var(--text-base);
  line-height: var(--leading-normal);
  color: var(--color-text);
  background-color: var(--color-white);
  min-height: 100vh;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

a {
  color: inherit;
  text-decoration: none;
  transition: color var(--transition-fast);
}

ul, ol {
  list-style: none;
}

button {
  font: inherit;
  cursor: pointer;
  border: none;
  background: none;
  color: inherit;
}

h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-display);
  line-height: var(--leading-tight);
  font-weight: var(--weight-bold);
  color: var(--color-primary);
}

h1 { font-size: var(--text-5xl); }
h2 { font-size: var(--text-4xl); }
h3 { font-size: var(--text-2xl); }
h4 { font-size: var(--text-xl); }

/* ============================================================
   Layout Utilities
   ============================================================ */

.container {
  width: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--content-padding);
}

.container--narrow {
  max-width: var(--max-width-narrow);
}

.container--wide {
  max-width: var(--max-width-wide);
}

.section {
  padding: var(--space-24) 0;
}

.section--sm { padding: var(--space-16) 0; }
.section--lg { padding: var(--space-32) 0; }

.section-label {
  display: inline-block;
  font-size: var(--text-sm);
  font-weight: var(--weight-semibold);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--color-secondary);
  margin-bottom: var(--space-3);
}

.section-title {
  font-size: var(--text-4xl);
  font-weight: var(--weight-bold);
  color: var(--color-primary);
  margin-bottom: var(--space-4);
  line-height: var(--leading-tight);
}

.section-subtitle {
  font-size: var(--text-lg);
  color: var(--color-text-light);
  max-width: 640px;
  line-height: var(--leading-normal);
}

.section-header {
  margin-bottom: var(--space-12);
}

.section-header--centered {
  text-align: center;
}

.section-header--centered .section-subtitle {
  margin: 0 auto;
}

/* ============================================================
   Buttons
   ============================================================ */

.btn {
  display: inline-flex;
  align-items: center;
  gap: var(--space-2);
  font-weight: var(--weight-semibold);
  font-size: var(--text-sm);
  padding: var(--space-3) var(--space-6);
  border-radius: var(--radius-sm);
  transition: all var(--transition-fast);
  white-space: nowrap;
  line-height: 1.4;
}

.btn--primary {
  background: var(--color-cta);
  color: var(--color-primary);
}

.btn--primary:hover {
  background: var(--color-cta-hover);
  transform: translateY(-1px);
}

.btn--outline {
  border: 1.5px solid var(--color-primary);
  color: var(--color-primary);
}

.btn--outline:hover {
  background: var(--color-primary);
  color: var(--color-white);
}

.btn--outline-light {
  border: 1.5px solid rgba(255,255,255,0.5);
  color: var(--color-white);
}

.btn--outline-light:hover {
  background: var(--color-white);
  color: var(--color-primary);
}

.btn--white {
  background: var(--color-white);
  color: var(--color-primary);
}

.btn--white:hover {
  background: var(--color-off-white);
}

.btn--link {
  padding: 0;
  color: var(--color-secondary);
  font-weight: var(--weight-semibold);
}

.btn--link::after {
  content: ' →';
  transition: transform var(--transition-fast);
}

.btn--link:hover::after {
  transform: translateX(4px);
}

.btn--lg {
  padding: var(--space-4) var(--space-8);
  font-size: var(--text-base);
}

/* ============================================================
   Header & Navigation
   ============================================================ */

.header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  background: var(--color-white);
  border-bottom: 1px solid var(--color-light-gray);
  transition: box-shadow var(--transition-base);
}

.header--scrolled {
  box-shadow: var(--shadow-md);
}

.header__inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
  max-width: var(--max-width-wide);
  margin: 0 auto;
  padding: 0 var(--content-padding);
}

.header__logo {
  display: flex;
  align-items: center;
  gap: var(--space-3);
  font-size: var(--text-xl);
  font-weight: var(--weight-bold);
  color: var(--color-primary);
  letter-spacing: -0.02em;
  flex-shrink: 0;
}

.header__logo-icon {
  width: 34px;
  height: 34px;
  border-radius: var(--radius-sm);
  background: var(--color-primary);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-white);
  font-weight: var(--weight-bold);
  font-size: var(--text-base);
}

/* Primary Nav */
.nav {
  display: flex;
  align-items: center;
}

.nav__list {
  display: flex;
  align-items: center;
  gap: var(--space-1);
}

.nav__link {
  display: block;
  padding: var(--space-2) var(--space-3);
  font-size: var(--text-sm);
  font-weight: var(--weight-medium);
  color: var(--color-text);
  border-radius: var(--radius-sm);
  transition: all var(--transition-fast);
  white-space: nowrap;
}

.nav__link:hover,
.nav__link.active {
  color: var(--color-secondary);
  background: oklch(97% 0.01 170);
}

.nav__link.has-dropdown::after {
  content: '';
  display: inline-block;
  width: 6px;
  height: 6px;
  border-right: 1.5px solid currentColor;
  border-bottom: 1.5px solid currentColor;
  transform: rotate(45deg);
  margin-left: var(--space-2);
  vertical-align: middle;
  transition: transform var(--transition-fast);
}

.nav__link.has-dropdown.open::after {
  transform: rotate(-135deg);
  margin-top: -2px;
}

/* Mega Menu */
.mega-menu {
  position: absolute;
  top: 100%;
  left: 0;
  right: 0;
  background: var(--color-white);
  border-top: 1px solid var(--color-light-gray);
  box-shadow: var(--shadow-lg);
  opacity: 0;
  visibility: hidden;
  transform: translateY(-8px);
  transition: all var(--transition-base);
  z-index: 999;
}

.mega-menu--visible {
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
}

.mega-menu__inner {
  max-width: var(--max-width-wide);
  margin: 0 auto;
  padding: var(--space-10) var(--content-padding);
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-12);
}

.mega-menu__column-title {
  font-size: var(--text-xs);
  font-weight: var(--weight-semibold);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--color-mid-gray);
  margin-bottom: var(--space-5);
  padding-bottom: var(--space-3);
  border-bottom: 1px solid var(--color-light-gray);
}

.mega-menu__links {
  display: flex;
  flex-direction: column;
  gap: var(--space-1);
}

.mega-menu__link {
  display: block;
  padding: var(--space-3) var(--space-3);
  font-size: var(--text-sm);
  color: var(--color-text);
  border-radius: var(--radius-sm);
  transition: all var(--transition-fast);
}

.mega-menu__link:hover {
  background: var(--color-off-white);
  color: var(--color-secondary);
  padding-left: var(--space-5);
}

/* Mobile menu toggle */
.mobile-toggle {
  display: none;
  width: 40px;
  height: 40px;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius-sm);
  z-index: 1001;
}

.mobile-toggle:hover {
  background: var(--color-off-white);
}

.mobile-toggle__bar {
  width: 22px;
  height: 2px;
  background: var(--color-primary);
  position: relative;
  transition: background var(--transition-base);
}

.mobile-toggle__bar::before,
.mobile-toggle__bar::after {
  content: '';
  position: absolute;
  left: 0;
  width: 100%;
  height: 2px;
  background: var(--color-primary);
  transition: all var(--transition-base);
}

.mobile-toggle__bar::before { top: -7px; }
.mobile-toggle__bar::after { top: 7px; }

.mobile-toggle--active .mobile-toggle__bar {
  background: transparent;
}

.mobile-toggle--active .mobile-toggle__bar::before {
  top: 0;
  transform: rotate(45deg);
}

.mobile-toggle--active .mobile-toggle__bar::after {
  top: 0;
  transform: rotate(-45deg);
}

/* Mobile Nav */
.mobile-nav {
  display: none;
  position: fixed;
  top: 72px;
  left: 0;
  right: 0;
  bottom: 0;
  background: var(--color-white);
  z-index: 998;
  overflow-y: auto;
  padding: var(--space-4) 0;
  opacity: 0;
  visibility: hidden;
  transition: all var(--transition-base);
}

.mobile-nav--open {
  opacity: 1;
  visibility: visible;
}

.mobile-nav__list {
  padding: 0 var(--content-padding);
}

.mobile-nav__item {
  border-bottom: 1px solid var(--color-light-gray);
}

.mobile-nav__link {
  display: block;
  padding: var(--space-4) 0;
  font-weight: var(--weight-medium);
  color: var(--color-text);
  transition: color var(--transition-fast);
}

.mobile-nav__link:hover {
  color: var(--color-secondary);
}

.mobile-nav__accordion-toggle {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  padding: var(--space-4) 0;
  font-weight: var(--weight-medium);
  color: var(--color-text);
  text-align: left;
}

.mobile-nav__accordion-toggle::after {
  content: '+';
  font-size: var(--text-xl);
  font-weight: var(--weight-normal);
  transition: transform var(--transition-base);
}

.mobile-nav__accordion-toggle--open::after {
  content: '−';
}

.mobile-nav__submenu {
  display: none;
  padding: 0 0 var(--space-4) var(--space-4);
}

.mobile-nav__submenu--open {
  display: block;
}

.mobile-nav__sub-link {
  display: block;
  padding: var(--space-2) 0;
  font-size: var(--text-sm);
  color: var(--color-text-light);
}

.mobile-nav__sub-label {
  font-size: var(--text-xs);
  font-weight: var(--weight-semibold);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--color-mid-gray);
  padding: var(--space-4) 0 var(--space-2) var(--space-4);
}

/* ============================================================
   Hero
   ============================================================ */

.hero {
  position: relative;
  min-height: 85vh;
  display: flex;
  align-items: center;
  background: var(--color-primary);
  overflow: hidden;
  margin-top: 72px;
}

.hero__bg {
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, oklch(20% 0.04 210) 0%, oklch(15% 0.03 230) 50%, oklch(25% 0.06 175) 100%);
}

.hero__bg-pattern {
  position: absolute;
  inset: 0;
  opacity: 0.06;
  background-image:
    linear-gradient(30deg, var(--color-white) 12%, transparent 12.5%, transparent 87%, var(--color-white) 87.5%, var(--color-white)),
    linear-gradient(150deg, var(--color-white) 12%, transparent 12.5%, transparent 87%, var(--color-white) 87.5%, var(--color-white)),
    linear-gradient(30deg, var(--color-white) 12%, transparent 12.5%, transparent 87%, var(--color-white) 87.5%, var(--color-white)),
    linear-gradient(150deg, var(--color-white) 12%, transparent 12.5%, transparent 87%, var(--color-white) 87.5%, var(--color-white));
  background-size: 80px 140px;
  background-position: 0 0, 0 0, 40px 70px, 40px 70px;
}

.hero__content {
  position: relative;
  z-index: 2;
  max-width: 720px;
  padding: var(--space-20) 0;
}

.hero__label {
  display: inline-block;
  font-size: var(--text-sm);
  font-weight: var(--weight-semibold);
  color: var(--color-cta);
  text-transform: uppercase;
  letter-spacing: 0.1em;
  margin-bottom: var(--space-6);
}

.hero__title {
  font-size: var(--text-6xl);
  font-weight: var(--weight-bold);
  color: var(--color-white);
  line-height: 1.1;
  margin-bottom: var(--space-6);
}

.hero__subtitle {
  font-size: var(--text-xl);
  color: oklch(80% 0.02 210);
  line-height: var(--leading-normal);
  margin-bottom: var(--space-8);
  max-width: 560px;
}

/* Hero variants */
.hero--page {
  min-height: 50vh;
}

.hero--page .hero__title {
  font-size: var(--text-5xl);
}

/* ============================================================
   Cards
   ============================================================ */

.card {
  background: var(--color-white);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: all var(--transition-base);
}

.card--shadow {
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--color-light-gray);
}

.card--shadow:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

.card__image {
  width: 100%;
  height: 200px;
  object-fit: cover;
}

.card__body {
  padding: var(--space-6);
}

.card__tag {
  display: inline-block;
  font-size: var(--text-xs);
  font-weight: var(--weight-semibold);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--color-secondary);
  margin-bottom: var(--space-3);
}

.card__title {
  font-size: var(--text-xl);
  font-weight: var(--weight-semibold);
  color: var(--color-primary);
  margin-bottom: var(--space-3);
  line-height: var(--leading-snug);
}

.card__text {
  font-size: var(--text-sm);
  color: var(--color-text-light);
  line-height: var(--leading-normal);
  margin-bottom: var(--space-4);
}

.card__meta {
  font-size: var(--text-xs);
  color: var(--color-mid-gray);
}

/* ============================================================
   Grid layouts
   ============================================================ */

.grid-2 { display: grid; grid-template-columns: repeat(2, 1fr); gap: var(--space-8); }
.grid-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: var(--space-8); }
.grid-4 { display: grid; grid-template-columns: repeat(4, 1fr); gap: var(--space-8); }

/* ============================================================
   What We Do — Vertical Tabs
   ============================================================ */

.what-we-do {
  display: grid;
  grid-template-columns: 320px 1fr;
  gap: var(--space-12);
  align-items: start;
}

.tabs-vertical {
  display: flex;
  flex-direction: column;
  gap: var(--space-1);
  border-right: 1px solid var(--color-light-gray);
  padding-right: var(--space-8);
}

.tab-btn {
  display: block;
  width: 100%;
  text-align: left;
  padding: var(--space-4) var(--space-5);
  font-size: var(--text-base);
  font-weight: var(--weight-medium);
  color: var(--color-text-light);
  border-radius: var(--radius-md);
  transition: all var(--transition-fast);
  border-left: 3px solid transparent;
}

.tab-btn:hover {
  background: var(--color-off-white);
  color: var(--color-text);
}

.tab-btn--active {
  background: oklch(97% 0.01 170);
  color: var(--color-secondary);
  font-weight: var(--weight-semibold);
  border-left-color: var(--color-secondary);
}

.tab-panel {
  display: none;
  animation: fadeIn var(--transition-base) ease;
}

.tab-panel--active {
  display: block;
}

.tab-panel__title {
  font-size: var(--text-3xl);
  font-weight: var(--weight-bold);
  color: var(--color-primary);
  margin-bottom: var(--space-4);
}

.tab-panel__text {
  font-size: var(--text-lg);
  color: var(--color-text-light);
  line-height: var(--leading-normal);
  margin-bottom: var(--space-6);
}

.tab-panel__list {
  margin-bottom: var(--space-8);
}

.tab-panel__list li {
  padding: var(--space-2) 0;
  padding-left: var(--space-6);
  position: relative;
  color: var(--color-text-light);
}

.tab-panel__list li::before {
  content: '';
  position: absolute;
  left: 0;
  top: 12px;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--color-secondary);
}

/* ============================================================
   Featured Insights Strip
   ============================================================ */

.featured-insights {
  padding: var(--space-12) 0;
  background: var(--color-off-white);
}

.featured-insights__grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-8);
}

.featured-card {
  display: flex;
  align-items: flex-start;
  gap: var(--space-4);
}

.featured-card__icon {
  flex-shrink: 0;
  width: 44px;
  height: 44px;
  border-radius: var(--radius-md);
  background: var(--color-primary);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-white);
  font-size: var(--text-lg);
}

.featured-card__title {
  font-size: var(--text-sm);
  font-weight: var(--weight-semibold);
  color: var(--color-primary);
  margin-bottom: var(--space-1);
}

.featured-card__text {
  font-size: var(--text-sm);
  color: var(--color-text-light);
  line-height: var(--leading-normal);
}

/* ============================================================
   Announcement Banner
   ============================================================ */

.announcement-banner {
  background: var(--color-secondary);
  padding: var(--space-5) 0;
}

.announcement-banner__inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-6);
}

.announcement-banner__text {
  color: var(--color-white);
  font-size: var(--text-sm);
  font-weight: var(--weight-medium);
}

.announcement-banner__dot {
  display: inline-block;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--color-cta);
  margin-right: var(--space-3);
  animation: pulse 2s infinite;
}

/* ============================================================
   Newsletter
   ============================================================ */

.newsletter {
  background: var(--color-primary);
  padding: var(--space-20) 0;
}

.newsletter__inner {
  max-width: 640px;
  margin: 0 auto;
  text-align: center;
}

.newsletter__title {
  font-size: var(--text-3xl);
  color: var(--color-white);
  margin-bottom: var(--space-4);
}

.newsletter__text {
  color: oklch(80% 0.02 210);
  font-size: var(--text-lg);
  margin-bottom: var(--space-8);
}

.newsletter__form {
  display: flex;
  gap: var(--space-3);
  max-width: 480px;
  margin: 0 auto var(--space-4);
}

.newsletter__input {
  flex: 1;
  padding: var(--space-3) var(--space-5);
  border: 1px solid oklch(50% 0.03 220);
  border-radius: var(--radius-sm);
  font-size: var(--text-sm);
  background: oklch(25% 0.03 215);
  color: var(--color-white);
  outline: none;
  transition: border-color var(--transition-fast);
}

.newsletter__input::placeholder {
  color: oklch(60% 0.02 215);
}

.newsletter__input:focus {
  border-color: var(--color-cta);
}

.newsletter__note {
  font-size: var(--text-xs);
  color: oklch(55% 0.03 215);
}

/* ============================================================
   Commitment Cards
   ============================================================ */

.commitment-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--space-8);
}

.commitment-card {
  padding: var(--space-8);
  border-radius: var(--radius-lg);
  background: var(--color-off-white);
  transition: all var(--transition-base);
  border: 1px solid transparent;
}

.commitment-card:hover {
  border-color: var(--color-light-gray);
  box-shadow: var(--shadow-md);
}

.commitment-card__icon {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-md);
  background: oklch(30% 0.07 175);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-white);
  font-size: var(--text-xl);
  margin-bottom: var(--space-5);
}

.commitment-card__title {
  font-size: var(--text-lg);
  font-weight: var(--weight-semibold);
  color: var(--color-primary);
  margin-bottom: var(--space-3);
}

.commitment-card__text {
  font-size: var(--text-sm);
  color: var(--color-text-light);
  line-height: var(--leading-normal);
  margin-bottom: var(--space-5);
}

/* ============================================================
   Service Cards (Overview)
   ============================================================ */

.services-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-8);
}

.service-card {
  padding: var(--space-8);
  border-radius: var(--radius-lg);
  background: var(--color-white);
  border: 1px solid var(--color-light-gray);
  transition: all var(--transition-base);
  display: flex;
  flex-direction: column;
}

.service-card:hover {
  box-shadow: var(--shadow-lg);
  border-color: transparent;
  transform: translateY(-3px);
}

.service-card__icon {
  width: 52px;
  height: 52px;
  border-radius: var(--radius-md);
  background: oklch(28% 0.06 185);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-white);
  font-size: var(--text-xl);
  margin-bottom: var(--space-5);
}

.service-card__title {
  font-size: var(--text-xl);
  font-weight: var(--weight-semibold);
  color: var(--color-primary);
  margin-bottom: var(--space-3);
}

.service-card__text {
  font-size: var(--text-sm);
  color: var(--color-text-light);
  line-height: var(--leading-normal);
  flex: 1;
  margin-bottom: var(--space-5);
}

/* ============================================================
   Capabilities Grid (Detail Pages)
   ============================================================ */

.capabilities-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-8);
}

.capability-card {
  padding: var(--space-8);
  border-radius: var(--radius-lg);
  background: var(--color-off-white);
  border: 1px solid var(--color-light-gray);
  transition: all var(--transition-base);
}

.capability-card:hover {
  background: var(--color-white);
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

.capability-card__title {
  font-size: var(--text-lg);
  font-weight: var(--weight-semibold);
  color: var(--color-primary);
  margin-bottom: var(--space-3);
}

.capability-card__text {
  font-size: var(--text-sm);
  color: var(--color-text-light);
  line-height: var(--leading-normal);
}

/* ============================================================
   Insights Cards
   ============================================================ */

.insights-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-8);
}

.insight-card {
  border-radius: var(--radius-lg);
  overflow: hidden;
  background: var(--color-white);
  border: 1px solid var(--color-light-gray);
  transition: all var(--transition-base);
}

.insight-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-3px);
}

.insight-card__image {
  height: 200px;
  background: oklch(30% 0.05 200);
  position: relative;
  overflow: hidden;
}

.insight-card__image-placeholder {
  width: 100%;
  height: 100%;
  background: linear-gradient(135deg, oklch(35% 0.06 200), oklch(25% 0.04 220));
  display: flex;
  align-items: center;
  justify-content: center;
  color: oklch(80% 0.03 200);
  font-size: var(--text-3xl);
}

.insight-card__body {
  padding: var(--space-6);
}

.insight-card__category {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  font-size: var(--text-xs);
  font-weight: var(--weight-semibold);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--color-secondary);
  margin-bottom: var(--space-3);
}

.insight-card__category-icon {
  font-size: var(--text-base);
}

.insight-card__title {
  font-size: var(--text-base);
  font-weight: var(--weight-semibold);
  color: var(--color-primary);
  line-height: var(--leading-snug);
  margin-bottom: var(--space-3);
}

.insight-card__date {
  font-size: var(--text-xs);
  color: var(--color-mid-gray);
}

/* ============================================================
   Partnership Highlight
   ============================================================ */

.partnership-highlight {
  background: var(--color-off-white);
  border-radius: var(--radius-xl);
  padding: var(--space-12);
  position: relative;
  overflow: hidden;
}

.partnership-highlight__inner {
  max-width: 720px;
}

.partnership-highlight__label {
  font-size: var(--text-xs);
  font-weight: var(--weight-semibold);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--color-secondary);
  margin-bottom: var(--space-4);
}

.partnership-highlight__title {
  font-size: var(--text-3xl);
  font-weight: var(--weight-bold);
  color: var(--color-primary);
  margin-bottom: var(--space-4);
}

.partnership-highlight__text {
  font-size: var(--text-lg);
  color: var(--color-text-light);
  line-height: var(--leading-normal);
}

.partnership-highlight__stats {
  display: flex;
  gap: var(--space-12);
  margin-top: var(--space-8);
}

.partnership-stat {
  text-align: center;
}

.partnership-stat__value {
  font-size: var(--text-4xl);
  font-weight: var(--weight-bold);
  color: var(--color-secondary);
  line-height: 1;
}

.partnership-stat__label {
  font-size: var(--text-sm);
  color: var(--color-text-light);
  margin-top: var(--space-2);
}

/* ============================================================
   About Statement
   ============================================================ */

.about-statement {
  padding: var(--space-24) 0;
  background: var(--color-white);
}

.about-statement__inner {
  max-width: 800px;
  margin: 0 auto;
  text-align: center;
}

.about-statement__text {
  font-size: var(--text-2xl);
  font-weight: var(--weight-medium);
  color: var(--color-text);
  line-height: var(--leading-normal);
  margin-bottom: var(--space-8);
}

/* ============================================================
   Testimonials
   ============================================================ */

.testimonial {
  background: var(--color-primary);
  border-radius: var(--radius-xl);
  padding: var(--space-12);
  color: var(--color-white);
  position: relative;
}

.testimonial__quote {
  font-size: var(--text-2xl);
  font-weight: var(--weight-medium);
  line-height: var(--leading-normal);
  margin-bottom: var(--space-6);
  font-style: italic;
}

.testimonial__quote::before {
  content: '"';
  font-size: var(--text-6xl);
  line-height: 0;
  color: var(--color-cta);
  vertical-align: bottom;
  margin-right: var(--space-2);
}

.testimonial__author {
  font-size: var(--text-sm);
  color: oklch(80% 0.02 210);
}

/* ============================================================
   Featured Topics Sidebar
   ============================================================ */

.featured-topics {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-3);
}

.featured-topic {
  display: inline-block;
  padding: var(--space-2) var(--space-5);
  font-size: var(--text-sm);
  font-weight: var(--weight-medium);
  color: var(--color-primary);
  background: var(--color-off-white);
  border-radius: 999px;
  border: 1px solid var(--color-light-gray);
  transition: all var(--transition-fast);
}

.featured-topic:hover {
  background: var(--color-primary);
  color: var(--color-white);
  border-color: var(--color-primary);
}

/* ============================================================
   Featured Partners Carousel
   ============================================================ */

.carousel {
  position: relative;
  overflow: hidden;
}

.carousel__track {
  display: flex;
  transition: transform var(--transition-slow);
}

.carousel__slide {
  flex: 0 0 100%;
  padding: 0;
}

.carousel__controls {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-4);
  margin-top: var(--space-8);
}

.carousel__btn {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  border: 1px solid var(--color-light-gray);
  background: var(--color-white);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--transition-fast);
  font-size: var(--text-lg);
  color: var(--color-primary);
}

.carousel__btn:hover {
  background: var(--color-primary);
  color: var(--color-white);
  border-color: var(--color-primary);
}

.carousel__dots {
  display: flex;
  gap: var(--space-2);
}

.carousel__dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--color-light-gray);
  transition: all var(--transition-fast);
}

.carousel__dot--active {
  background: var(--color-secondary);
  width: 24px;
  border-radius: 4px;
}

/* ============================================================
   Breadcrumb
   ============================================================ */

.breadcrumb {
  padding: var(--space-4) 0;
  background: var(--color-off-white);
  border-bottom: 1px solid var(--color-light-gray);
  margin-top: 72px;
}

.breadcrumb__list {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  font-size: var(--text-sm);
  color: var(--color-mid-gray);
}

.breadcrumb__link {
  color: var(--color-text-light);
}

.breadcrumb__link:hover {
  color: var(--color-secondary);
}

.breadcrumb__separator {
  color: var(--color-mid-gray);
}

.breadcrumb__current {
  color: var(--color-text);
  font-weight: var(--weight-medium);
}

/* ============================================================
   Related sections
   ============================================================ */

.related-services {
  background: var(--color-off-white);
}

.related-services__grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-6);
}

.related-service-card {
  padding: var(--space-6);
  background: var(--color-white);
  border-radius: var(--radius-lg);
  border: 1px solid var(--color-light-gray);
  transition: all var(--transition-base);
}

.related-service-card:hover {
  box-shadow: var(--shadow-md);
}

.related-service-card__title {
  font-size: var(--text-lg);
  font-weight: var(--weight-semibold);
  color: var(--color-primary);
  margin-bottom: var(--space-2);
}

.related-service-card__text {
  font-size: var(--text-sm);
  color: var(--color-text-light);
  line-height: var(--leading-normal);
  margin-bottom: var(--space-4);
}

/* ============================================================
   Deal Flow CTA
   ============================================================ */

.deal-flow-cta {
  background: var(--color-primary);
  border-radius: var(--radius-xl);
  padding: var(--space-12);
  text-align: center;
}

.deal-flow-cta__title {
  font-size: var(--text-3xl);
  font-weight: var(--weight-bold);
  color: var(--color-white);
  margin-bottom: var(--space-4);
}

.deal-flow-cta__text {
  font-size: var(--text-lg);
  color: oklch(80% 0.02 210);
  margin-bottom: var(--space-8);
  max-width: 560px;
  margin-left: auto;
  margin-right: auto;
}

/* ============================================================
   Property Types CTA
   ============================================================ */

.property-types-bar {
  padding: var(--space-8) var(--space-10);
  background: var(--color-off-white);
  border-radius: var(--radius-lg);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-8);
}

.property-types-bar__text {
  font-size: var(--text-base);
  font-weight: var(--weight-medium);
  color: var(--color-text);
}

/* ============================================================
   Footer
   ============================================================ */

.footer {
  background: var(--color-primary);
  color: oklch(80% 0.02 210);
  padding: var(--space-20) 0 var(--space-10);
}

.footer__grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: var(--space-12);
  margin-bottom: var(--space-16);
}

.footer__brand-name {
  font-size: var(--text-xl);
  font-weight: var(--weight-bold);
  color: var(--color-white);
  margin-bottom: var(--space-4);
}

.footer__brand-text {
  font-size: var(--text-sm);
  line-height: var(--leading-normal);
  margin-bottom: var(--space-6);
  max-width: 300px;
}

.footer__heading {
  font-size: var(--text-sm);
  font-weight: var(--weight-semibold);
  color: var(--color-white);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: var(--space-5);
}

.footer__links {
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
}

.footer__link {
  font-size: var(--text-sm);
  color: oklch(70% 0.02 210);
  transition: color var(--transition-fast);
}

.footer__link:hover {
  color: var(--color-white);
}

.footer__bottom {
  border-top: 1px solid oklch(35% 0.03 215);
  padding-top: var(--space-8);
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: var(--space-4);
}

.footer__legal {
  display: flex;
  align-items: center;
  gap: var(--space-6);
  flex-wrap: wrap;
}

.footer__legal-link {
  font-size: var(--text-xs);
  color: oklch(60% 0.03 215);
}

.footer__legal-link:hover {
  color: var(--color-white);
}

.footer__copyright {
  font-size: var(--text-xs);
  color: oklch(55% 0.03 215);
}

/* ============================================================
   Intro Statement (Page-level)
   ============================================================ */

.intro-statement {
  padding: var(--space-12) 0 var(--space-8);
}

.intro-statement__text {
  font-size: var(--text-xl);
  color: var(--color-text-light);
  line-height: var(--leading-normal);
  max-width: 800px;
}

/* ============================================================
   Animations
   ============================================================ */

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.5; }
}

@keyframes slideInUp {
  from { opacity: 0; transform: translateY(20px); }
  to { opacity: 1; transform: translateY(0); }
}

.animate-in {
  animation: slideInUp 0.5s ease both;
}

/* ============================================================
   Responsive — Tablet
   ============================================================ */

@media (max-width: 1024px) {
  :root {
    --text-5xl: 2.5rem;
    --text-6xl: 3rem;
  }

  .grid-4,
  .commitment-grid { grid-template-columns: repeat(2, 1fr); }

  .grid-3,
  .services-grid,
  .insights-grid,
  .capabilities-grid,
  .featured-insights__grid { grid-template-columns: repeat(2, 1fr); }

  .what-we-do {
    grid-template-columns: 240px 1fr;
  }

  .footer__grid {
    grid-template-columns: 1fr 1fr;
  }

  .announcement-banner__inner {
    flex-direction: column;
    text-align: center;
  }
}

/* ============================================================
   Responsive — Mobile
   ============================================================ */

@media (max-width: 768px) {
  :root {
    --text-4xl: 1.75rem;
    --text-5xl: 2rem;
    --text-6xl: 2.5rem;
    --content-padding: var(--space-4);
  }

  .section { padding: var(--space-16) 0; }

  /* Header */
  .header__inner { height: 60px; }

  .nav { display: none; }

  .mobile-toggle { display: flex; }
  .mobile-nav { display: block; }

  /* Hero */
  .hero { min-height: 70vh; margin-top: 60px; }
  .hero--page { min-height: 35vh; }
  .hero__title { font-size: var(--text-4xl); }
  .hero__subtitle { font-size: var(--text-base); }

  /* Grids */
  .grid-2,
  .grid-3,
  .grid-4,
  .services-grid,
  .insights-grid,
  .capabilities-grid,
  .commitment-grid,
  .featured-insights__grid { grid-template-columns: 1fr; }

  /* What We Do */
  .what-we-do {
    grid-template-columns: 1fr;
    gap: var(--space-6);
  }

  .tabs-vertical {
    flex-direction: row;
    overflow-x: auto;
    border-right: none;
    border-bottom: 1px solid var(--color-light-gray);
    padding-right: 0;
    padding-bottom: var(--space-4);
    gap: var(--space-2);
  }

  .tab-btn {
    white-space: nowrap;
    border-left: none;
    border-bottom: 3px solid transparent;
    font-size: var(--text-sm);
    padding: var(--space-3) var(--space-4);
  }

  .tab-btn--active {
    border-left-color: transparent;
    border-bottom-color: var(--color-secondary);
  }

  /* Newsletter */
  .newsletter__form {
    flex-direction: column;
  }

  /* Mega menu */
  .mega-menu__inner {
    grid-template-columns: 1fr;
  }

  /* Footer */
  .footer__grid {
    grid-template-columns: 1fr;
    gap: var(--space-8);
  }

  .footer__bottom {
    flex-direction: column;
    text-align: center;
  }

  .footer__legal {
    justify-content: center;
  }

  /* Breadcrumb */
  .breadcrumb { margin-top: 60px; }

  /* Detail pages */
  .partnership-highlight__stats {
    flex-direction: column;
    gap: var(--space-6);
  }

  .property-types-bar {
    flex-direction: column;
    text-align: center;
  }

  .about-statement__text {
    font-size: var(--text-lg);
  }
}

/* ============================================================
   Large screens
   ============================================================ */

@media (min-width: 1400px) {
  .hero__title {
    font-size: 4rem;
  }
}
